H("675.d.1.I",3,"What can a student learn by visiting a university's computer science department website?","degree requirements and available courses",["the weather in other countries","game scores","lunch menus of other schools"],"Department sites list program details.")
H("675.d.1.I",4,"When comparing programs, which question most directly shows career support?","Does the program offer internships and career placement help?",["What color is the library?","How many lamps are in the hall?","Is the mascot an animal?"],"Placement help supports careers.")
H("675.d.2.A",3,"Showing only the essential features of an object while hiding its complexity is:","data abstraction",["data corruption","data loss","data casting"],"Abstraction exposes what matters.")
H("675.d.2.A",4,"Which object-oriented principle lets a class reuse behavior from another class?","inheritance",["input validation","file buffering","garbage collection"],"Subclasses inherit from parents.")
H("675.d.2.B",3,"In a hierarchy with Shape as the parent and Circle and Square as children, Shape is the:","superclass",["subclass","interface variable","constructor"],"The parent class is the superclass.")
H("675.d.2.B",4,"Where should behavior shared by all shapes, such as getColor(), be placed?","in the superclass",["in every subclass separately","in the main method","in a comment"],"Shared code belongs in the parent.")
H("675.d.2.C",3,"In a UML class diagram, a class is usually drawn as a:","box divided into name, attributes and methods",["circle with arrows","triangle only","single line"],"UML class boxes have three sections.")
H("675.d.2.C",4,"A UML minus sign before an attribute usually means it is:","private",["public","static","abstract"],"UML uses - for private and + for public.")
H("675.d.2.D",3,"Selection sort works by repeatedly:","finding the smallest remaining item and placing it next",["merging two halves","swapping neighbors only","hashing each item"],"It selects the minimum each pass.")
H("675.d.2.D",4,"Which sort picks an element and places smaller items before it and larger items after it?","quicksort",["bubble sort","selection sort","insertion sort"],"Quicksort partitions around a pivot.")
H("675.d.2.E",3,"A data structure that stores key-value pairs for fast lookup is a:","hash map",["stack","queue","linked list"],"Hash maps look up values by key quickly.")
H("675.d.2.E",4,"Which structure is best for always quickly retrieving the highest-priority item?","priority queue",["plain array in random order","stack","text file"],"Priority queues order by priority.")
H("675.d.3.A",3,"A shared repository such as Git lets team members:","merge their changes into a common project",["avoid communication","lose version history","edit without saving"],"Repositories coordinate team changes.")
H("675.d.3.A",4,"Before pushing code to a shared repository, a developer should usually first:","pull the latest changes and resolve conflicts",["delete the branch","disable tests","rename all files"],"Pulling first avoids overwriting teammates.")
H("675.d.3.B",3,"In a design team, a daily short stand-up meeting is used to:","share progress and blockers",["avoid planning","assign blame","skip coding"],"Stand-ups keep everyone aligned.")
H("675.d.3.B",4,"A team member's merge changes overwrite a teammate's work. Which practice most likely prevents this?","frequent communication and use of branches",["working alone on one file","disabling version control","avoiding code review"],"Branches and communication prevent conflicts.")
H("675.d.4.A",3,"A ragged array is a 2-D array in which:","rows can have different lengths",["all rows must be identical","there are no rows","every row has one element"],"Rows in a ragged array vary in size.")
H("675.d.4.A",4,"In Java, how can you get the length of row 2 of a 2-D array a?","a[2].length",["a.length[2]","length(a,2)","a.row(2)"],"Each row is its own array.")
H("675.d.4.B",3,"In a singly linked list, each node stores data and a reference to the:","next node",["previous node only","array index","file path"],"Nodes link forward.")
H("675.d.4.B",4,"When inserting a new node at the front of a linked list, you must update the:","head reference",["tail's data only","array length","compiler settings"],"The head must point to the new node.")
H("675.d.4.C",3,"Traversing a linked list from the head until a node's next is null visits:","every node in order",["only the first node","nodes in random order","only the last node"],"Follow next references to the end.")
H("675.d.4.C",4,"Deleting a node from the middle of a singly linked list requires making the previous node's next reference point to the:","node after the deleted one",["head of the list","deleted node itself","null always"],"This bypasses the removed node.")
H("675.d.4.D",3,"A linked list whose nodes each contain another linked list is an example of a:","composite data structure",["primitive type","syntax error","simple variable"],"Structures can be nested.")
H("675.d.4.D",4,"A graph stored as an array of lists, where each list holds a vertex's neighbors, is called an:","adjacency list",["ordered pair","hash digest","stack frame"],"Adjacency lists store neighbors.")
H("675.d.4.E",3,"Popping from a stack removes the item that was:","most recently pushed",["first pushed","largest","smallest"],"Stacks are last-in, first-out.")
H("675.d.4.E",4,"In a binary search tree, values smaller than a node are stored in its:","left subtree",["right subtree","parent only","root only"],"Smaller values go left.")
H("675.d.4.F",3,"A set data structure does not allow:","duplicate elements",["any elements","searching","traversal"],"Sets store unique items.")
H("675.d.4.F",4,"A hash-based set typically offers membership checks in about:","constant time on average",["linear time always","exponential time","no checks possible"],"Hashing gives near-constant lookup.")
H("675.d.4.G",3,"In a map, each key is associated with one:","value",["loop","compiler","class file"],"Maps pair keys with values.")
H("675.d.4.G",4,"A program counts how many times each word appears in a text. Which structure is the most natural?","a map from words to counts",["a stack of letters","a single integer","a two-dimensional boolean grid"],"Words are keys and counts are values.")
H("675.d.4.H",3,"To add new lines to the end of an existing text file without erasing it, open the file in:","append mode",["delete mode","read-only mode","compile mode"],"Append mode adds to the end.")
H("675.d.4.H",4,"Opening an existing file in write mode (not append) usually:","erases its previous contents",["adds to the end","makes a backup","locks it forever"],"Write mode truncates the file.")
H("675.d.5.A",3,"What is 5 & 3 using bitwise AND (5 = 101, 3 = 011)?","1",["0","3","7"],"Only the last bit is set in both: 001.")
H("675.d.5.A",4,"What is 6 | 3 using bitwise OR (6 = 110, 3 = 011)?","7",["3","6","2"],"110 OR 011 is 111, which is 7.")
H("675.d.5.B",3,"What does int r = (5 > 3) ? 10 : 20; assign to r?","10",["20","5","3"],"The condition is true, so the first value is used.")
H("675.d.5.B",4,"What does (7 < 4) ? 'yes' : 'no' evaluate to?","no",["yes","7","4"],"The condition is false, so the second value is used.")
H("675.d.5.C",3,"Each recursive call to a method is typically stored on the:","call stack",["hard drive","heap only","clipboard"],"Method calls use the call stack.")
H("675.d.5.C",4,"A recursive method with no base case will most likely cause:","a stack overflow error",["a faster program","a syntax highlight","a smaller file"],"Calls never stop and exhaust the stack.")
H("675.d.5.D",3,"A hash function maps a key to:","an index in a table",["a random color","a printer","an image"],"Hashing computes a table position.")
H("675.d.5.D",4,"When two different keys produce the same hash index, this is called a:","collision",["closure","cascade","cast"],"Collisions must be handled.")
H("675.d.5.E",3,"To add two matrices, they must have:","the same dimensions",["different sizes","one row each","only zeros"],"Addition works element by element.")
H("675.d.5.E",4,"Which output repeats a pattern at smaller and smaller scales?","a fractal",["a flat file","a checksum","an array index"],"Fractals are self-similar.")
H("675.d.5.F",3,"A program that handles invalid user input without crashing is showing:","robust behavior",["fragile design","syntax errors","dead code"],"Robust programs handle bad input.")
H("675.d.5.F",4,"Which Java feature lets a program respond to runtime errors without ending abruptly?","try-catch exception handling",["static import","string concatenation","array resizing"],"Exceptions can be caught and handled.")
H("675.d.6.A",3,"Consistent indentation and meaningful names primarily support:","code maintenance",["slower execution","larger files","hidden bugs"],"Readable code is easier to maintain.")
H("675.d.6.A",4,"A header comment at the top of a class usually describes:","its purpose and author",["the monitor size","unrelated trivia","a cooking recipe"],"Headers document purpose and ownership.")
H("675.d.6.B",3,"An assertion in a program states:","a condition that is expected to be true",["a comment ignored by people","a loop count","a file name"],"Assertions document assumptions.")
H("675.d.6.B",4,"In Java, an assert statement that fails (when enabled) typically:","throws an AssertionError",["prints a joke","deletes the file","restarts the loop"],"A failed assertion raises an error.")
H("675.d.6.C",3,"Which Boolean expression asserts that count is never negative?","count >= 0",["count equals 0 exactly","count is negative","count is undefined"],"Non-negative means at least zero.")
H("675.d.6.C",4,"To assert that an array index i is valid for array a, the expression should check that:","i is at least 0 and less than a.length",["i equals a.length","i is greater than a.length","i is negative"],"Valid indexes run from 0 to length minus 1.")
H("675.d.6.D",3,"A loop invariant is a condition that is:","true before and after each iteration",["true only at the end","never true","changed by the compiler"],"Invariants hold throughout the loop.")
H("675.d.6.D",4,"An invariant of a bank account class might be that the balance is:","never below zero",["always exactly 100","a string","hidden from the class"],"Invariants state rules that always hold.")
H("675.d.7.A",3,"In a program flowchart, the diamond-shaped symbol is used where the program must make a:","decision",["start point","output only","comment"],"Diamonds mark yes/no branches.")
H("675.d.7.A",4,"A system diagram showing a user, an app, and a database with arrows between them illustrates:","how components interact",["how to compile","a loop count","the font of the app"],"System diagrams show relationships.")
H("675.d.7.B",3,"Two programs exchange data over the web using a defined:","API",["font","wallpaper","cursor"],"APIs define how programs communicate.")
H("675.d.7.B",4,"Before building a program-to-program interface, developers should first:","gather requirements from both sides",["delete existing data","ignore documentation","skip design"],"Requirements guide the interface design.")
H("675.d.7.C",3,"Assembly language is called a low-level language because it:","maps closely to machine instructions",["resembles English sentences","hides all hardware","cannot be translated"],"Assembly is near the hardware.")
H("675.d.7.C",4,"A program that translates assembly code into machine code is a(n):","assembler",["browser","spreadsheet","debugger"],"Assemblers produce machine code.")
H("675.d.7.D",3,"A short script that explores how a function behaves with different inputs is useful for:","discovering and testing ideas",["permanently deleting code","avoiding questions","formatting printers"],"Exploratory code reveals behavior.")
H("675.d.7.D",4,"A program that loops through numbers to find how many are prime is a:","discovery program",["compiler","firewall","operating system"],"It explores a mathematical question.")
H("675.d.7.E",3,"A shell script is a file containing:","commands the operating system can run in order",["only images","a printer driver","a spreadsheet"],"Scripts automate command sequences.")
H("675.d.7.E",4,"A script that backs up a folder every night uses the operating system's:","scheduler (such as cron or Task Scheduler)",["screen saver","clipboard","spell checker"],"Schedulers run tasks automatically.")
H("675.d.7.F",3,"Validating and sanitizing user input before using it helps prevent:","injection attacks",["faster loading","longer variable names","bigger fonts"],"Untrusted input can inject malicious commands.")
H("675.d.7.F",4,"Storing passwords as salted hashes instead of plain text is a best practice because:","a leaked database does not reveal the actual passwords",["it makes passwords shorter","it removes the need for logins","it speeds up the network"],"Hashes protect stored credentials.")
H("675.d.7.G",3,"Machine learning models that generate text or images are an example of an emerging trend called:","generative AI",["punch cards","floppy disks","dial-up"],"Generative AI is a current trend.")
H("675.d.7.G",4,"Which is a recent technology trend in computing?","cloud-based services running large AI models",["manual typewriters","fax-only offices","mechanical calculators"],"Cloud AI is an emerging trend.")
H("676.d.1.A",3,"Which entry-level role monitors alerts and investigates suspicious activity for an organization?","security analyst",["graphic designer","bus driver","food inspector"],"Analysts watch for and investigate threats.")
H("676.d.1.A",4,"An internship at a security operations center would most likely involve:","watching logs and alerts under supervision",["painting office walls","designing logos","repairing printers only"],"SOC interns support monitoring.")
H("676.d.1.B",3,"Which resource is best for researching typical pay and job outlook for information security analysts?","the U.S. Bureau of Labor Statistics Occupational Outlook Handbook",["a random chat message","an unsourced meme","an old rumor"],"BLS publishes reliable career data.")
H("676.d.1.B",4,"Networking with professionals through clubs and competitions helps a student:","learn about careers and make professional contacts",["avoid learning skills","hide qualifications","lose job leads"],"Networking opens doors and information.")
H("676.d.1.C",3,"CompTIA Security+ is an example of a:","cybersecurity certification",["video game","operating system","programming language"],"Security+ is an entry-level security credential.")
H("676.d.1.C",4,"Which certification is specifically known for ethical hacking?","Certified Ethical Hacker (CEH)",["Certified Public Accountant","Food Handler Card","Driver License"],"CEH focuses on authorized penetration techniques.")
H("676.d.1.D",3,"A penetration tester's role is to:","legally attempt to break into systems to find weaknesses",["design company logos","answer billing calls","install carpet"],"Pen testers simulate attacks with permission.")
H("676.d.1.D",4,"Which role manages an organization's overall security strategy and policies?","chief information security officer (CISO)",["intern photographer","payroll clerk","delivery driver"],"The CISO leads security strategy.")
H("676.d.2.A",3,"Using someone else's account without permission, even if you know the password, is:","unauthorized access",["good teamwork","a harmless shortcut","required by law"],"Permission is what makes access authorized.")
H("676.d.2.A",4,"An ethical response when you find a security flaw on a school website is to:","report it to the administrators without exploiting it",["post it publicly to embarrass them","use it to change grades","sell the information"],"Responsible disclosure helps fix the flaw.")
H("676.d.2.B",3,"In the U.S., the Computer Fraud and Abuse Act mainly makes it illegal to:","access computers without authorization",["own a laptop","use a password","buy software"],"The CFAA targets unauthorized access.")
H("676.d.2.B",4,"The European Union's GDPR is a law mainly about:","protecting personal data and privacy",["regulating video game ratings","setting internet speeds","taxing software sales"],"GDPR governs personal data.")
H("676.d.2.C",3,"The 2017 WannaCry attack spread worldwide by encrypting files and demanding payment, making it a:","ransomware attack",["phishing newsletter","hardware recall","spreadsheet error"],"WannaCry was ransomware.")
H("676.d.2.C",4,"The 2013 Target data breach began when attackers used credentials stolen from a:","third-party vendor",["school student","local newspaper","weather service"],"Vendor access was the entry point.")
H("676.d.2.D",3,"A coworker asks you to share your login so they can finish a report. The best response is to:","decline and have them request their own access",["share it quickly","email it","post it on a note"],"Credentials should never be shared.")
H("676.d.2.D",4,"A friend offers pirated paid software as a gift. Considering law and ethics, you should:","decline and use a licensed or free legal alternative",["accept and share it","sell it","hide the source"],"Piracy is illegal and unethical.")
H("676.d.2.E",3,"An attacker calls pretending to be IT support to get your password. This tactic is:","social engineering",["disk defragmentation","port forwarding","cache clearing"],"It manipulates people rather than technology.")
H("676.d.2.E",4,"Software designed to damage or gain unauthorized access to a system is called:","malware",["firmware","freeware","middleware"],"Malware is malicious software.")
H("676.d.2.F",3,"Why should you cite sources when using information from a security report?","to give credit and let readers verify the information",["to make the report longer","to hide where the data came from","to avoid reading the report"],"Citations give credit and support verification.")
H("676.d.2.F",4,"Which item is a necessary part of most citations?","author and title of the source",["a favorite color","the reader's address","a random number"],"Citations identify the work and its creator.")
H("676.d.3.A",3,"Which is a common motivation for cybercriminals?","financial gain",["needing sleep","bus schedules","weather curiosity"],"Many attacks aim to make money.")
H("676.d.3.A",4,"Some attackers hack to promote a political or social cause rather than for money. They are motivated by:","ideology or activism",["boredom with television","a favorite food","shoe size"],"Hacktivists act for a cause.")
H("676.d.3.B",3,"A group that attacks systems to promote a social or political message is called:","hacktivists",["script editors","system patches","network cables"],"Hacktivists mix hacking and activism.")
H("676.d.3.B",4,"Attacks sponsored by a government to spy on other nations are carried out by:","state-sponsored actors",["local hobbyists only","random pop-ups","hardware vendors"],"Nation-states run espionage campaigns.")
H("676.d.3.C",3,"A cyberattack on a hospital that locks patient records can:","delay patient care and endanger lives",["improve patient care","reduce all costs","make the network faster"],"Hospitals depend on data access.")
H("676.d.3.C",4,"Large-scale cyberattacks can harm society by disrupting:","banking, utilities and communications",["only paper mail","only music","nothing at all"],"Modern services depend on networks.")
H("676.d.3.D",3,"A hacker who breaks into systems with permission to help improve security is a:","white hat",["black hat","red flag","blue screen"],"White hats are ethical hackers.")
H("676.d.3.D",4,"A hacker who looks for flaws without permission but may report them rather than exploit them is often called a:","gray hat",["contracted pen tester","ransomware author","system administrator"],"Gray hats operate between legal lines.")
H("676.d.3.E",3,"Ethical hackers differ from criminals mainly because they have:","written permission to test the system",["faster computers","secret passwords","more followers"],"Authorization makes testing legal.")
H("676.d.3.E",4,"Hacking a company's network without permission, even without stealing anything, can result in:","criminal charges and fines",["a free reward","a promotion","a certificate"],"Unauthorized access is illegal.")
H("676.d.4.A",3,"Cyberterrorism is the use of attacks on computer systems to:","cause fear, disruption or harm for political aims",["improve typing speed","sell office furniture","teach coding"],"Cyberterrorism pursues political goals through fear.")
H("676.d.4.A",4,"Hacktivism differs from cyberterrorism in that hacktivists usually aim mainly to:","protest or spread a message",["cause mass physical casualties","sell stolen goods","repair networks"],"Hacktivism is typically protest-driven.")
H("676.d.4.B",3,"One difference between cyberterrorism and physical terrorism is that cyberattacks can be launched:","remotely from anywhere in the world",["only from inside the target building","only in daylight","only with explosives"],"Attackers need only a network connection.")
H("676.d.4.B",4,"Terrorism carried out by citizens against their own country's targets is called:","domestic terrorism",["international terrorism","foreign trade","state tourism"],"Domestic means within the same country.")
H("676.d.4.C",3,"Collecting information about a target before an attack or defense is called:","intelligence gathering",["data deletion","file compression","screen mirroring"],"Reconnaissance gathers intelligence.")
H("676.d.4.C",4,"Using public sources like websites and social media to collect information is known as:","open-source intelligence (OSINT)",["packet loss","disk imaging","rootkit install"],"OSINT uses publicly available data.")
H("676.d.4.D",3,"Why do governments invest in cyber defense?","to protect critical systems and national security",["to slow the economy","to reduce passwords","to remove all computers"],"Cyber defense protects national interests.")
H("676.d.4.D",4,"A corporation's cyber defense protects:","its customer data and trade secrets",["its competitors' data","only its logo","nothing digital"],"Companies guard valuable data.")
H("676.d.4.E",3,"Strong cyber defense supports the global economy by:","keeping online commerce and finance trustworthy",["stopping all trade","raising all prices","removing banks"],"Trust underpins digital business.")
H("676.d.4.E",4,"When consumers lose trust in online security, the likely economic effect is:","less online shopping and banking",["more online payments","free internet","lower inflation always"],"Distrust reduces digital activity.")
H("676.d.4.F",3,"Which is an example of public infrastructure targeted by cyberattacks?","the electrical power grid",["a private diary","a toy store","a cookbook"],"Power grids are critical infrastructure.")
H("676.d.4.F",4,"A successful attack on a water treatment plant's control system could:","endanger public health and safety",["improve water quality automatically","reduce the need for pipes","have no effect"],"Control systems manage safe treatment.")
H("676.d.5.A",3,"Privacy is a person's ability to:","control who has access to their personal information",["see everyone's data","avoid all technology","share everything"],"Privacy is about control over information.")
H("676.d.5.A",4,"Why is privacy valuable to individuals?","it protects safety, freedom and personal choice",["it makes passwords unnecessary","it speeds up internet","it removes laws"],"Privacy shields people from harm and pressure.")
H("676.d.5.B",3,"The trail of data you leave by browsing, posting and using apps is your:","digital footprint",["hard drive","file path","screen time bar"],"Your footprint is your online data trail.")
H("676.d.5.B",4,"A negative impact of a large digital footprint can be:","employers or others finding old posts about you",["faster downloads","fewer ads","stronger passwords"],"Old posts can surface later.")
H("676.d.5.C",3,"Smart speakers and cameras raise privacy concerns because they can:","collect data about people at home",["lower electricity","improve printing","remove viruses"],"Always-on sensors gather personal data.")
H("676.d.5.C",4,"Facial recognition in public places raises concerns mainly about:","tracking people without their consent",["screen resolution","battery life","typing speed"],"It enables mass surveillance.")
H("676.d.5.D",3,"Repeated online messages meant to harass or humiliate someone are called:","cyberbullying",["network sharing","cloud syncing","file streaming"],"This is harassment via technology.")
H("676.d.5.D",4,"A possible sign that a student is being cyberbullied is:","becoming upset after using a phone and avoiding school",["sleeping better","getting more invitations","feeling more confident online"],"Distress tied to devices can signal bullying.")
H("676.d.5.E",3,"A good first step if you are targeted by cyberbullying is to:","save evidence and tell a trusted adult",["reply with worse insults","delete the evidence","post personal details of the bully"],"Evidence and adult help support action.")
H("676.d.5.E",4,"Most social media platforms let users deal with abusive accounts by:","blocking and reporting them",["sharing their messages widely","ignoring settings","paying them"],"Block and report tools stop contact and alert moderators.")
H("676.d.6.A",3,"Which is an example of personally identifiable information (PII)?","a Social Security number",["a favorite color","a public weather report","a movie title"],"SSNs identify specific people.")
H("676.d.6.A",4,"PII is information that can be used to:","identify a specific person",["speed up a computer","print a document","color a screen"],"PII points to an individual.")
H("676.d.6.B",3,"Sharing your full birth date and address online increases the risk of:","identity theft",["faster internet","better grades","fewer emails"],"Criminals use PII to impersonate victims.")
H("676.d.6.B",4,"A benefit of sharing PII with a trusted bank is that it:","allows the bank to verify you and provide services",["makes your account public","removes security","guarantees no fraud"],"Verification enables legitimate services.")
H("676.d.6.C",3,"A flashlight app asking for access to your contacts and microphone is requesting:","unnecessary permissions",["standard lighting","a battery update","a screen repair"],"The app does not need that data.")
H("676.d.6.C",4,"Granting excessive app permissions can let an app:","collect or expose data it does not need",["increase battery life","fix bugs","block ads automatically"],"Extra permissions expand data exposure.")
H("676.d.6.D",3,"Allowing a third-party app to access your social media account can risk:","your data being shared or misused",["a stronger password","less data sharing","free storage"],"Third parties may mishandle data.")
H("676.d.6.D",4,"To limit risk, a user should periodically:","review and remove third-party app access",["grant every request","share passwords","disable updates"],"Pruning access reduces exposure.")
H("676.d.6.E",3,"Clicking 'I agree' on terms of service without reading can mean you:","accept data collection or sharing you did not review",["receive extra security","lose no rights","get a refund"],"Terms often include data permissions.")
H("676.d.6.E",4,"A terms-of-service document is a:","legal agreement between user and provider",["virus signature","password list","network map"],"ToS sets legal rules of use.")
H("676.d.7.A",3,"Cybersecurity is the practice of:","protecting systems, networks and data from digital attacks",["building faster screens","designing fonts","writing music"],"Cybersecurity defends against digital threats.")
H("676.d.7.A",4,"Information security is broader than cybersecurity in that it protects information:","in any form, including paper",["only on websites","only in clouds","only in email"],"Infosec covers all information formats.")
H("676.d.7.B",3,"A risk assessment identifies:","threats, vulnerabilities and potential impact",["the best desktop wallpaper","only the cheapest tools","employee birthdays"],"Assessments evaluate what could go wrong.")
H("676.d.7.B",4,"Risk is commonly estimated by considering the likelihood of an event and its:","impact",["color","shape","speed of typing"],"Risk combines likelihood and impact.")
H("676.d.7.C",3,"In the CIA triad, 'confidentiality' means:","only authorized people can access information",["data is never changed by anyone","systems are always online","files are always compressed"],"Confidentiality restricts access.")
H("676.d.7.C",4,"Keeping data accurate and unaltered by unauthorized users is the goal of:","integrity",["availability","portability","anonymity"],"Integrity protects accuracy.")
H("676.d.7.D",3,"Using the same easy password everywhere is convenient but reduces:","security",["screen size","battery life","file count"],"Convenience often weakens protection.")
H("676.d.7.D",4,"Requiring multi-factor authentication improves security but may reduce:","convenience",["encryption","accuracy of logs","server uptime"],"Extra steps slow users down.")
H("676.d.7.E",3,"After detecting a breach, the first priority is usually to:","contain the incident to stop further damage",["announce a sale","delete all logs","rename the servers"],"Containment limits the spread.")
H("676.d.7.E",4,"An incident response plan typically includes preparation, detection, containment, eradication, recovery and:","lessons learned",["advertising","hiring a mascot","a holiday party"],"Reviews improve future response.")
H("676.d.7.F",3,"Locks, badges and security cameras address which domain of security?","physical security",["network security","cloud billing","software licensing"],"These protect physical spaces.")
H("676.d.7.F",4,"Misconfigured cloud storage that exposes data publicly is a challenge in:","cloud security",["physical security","print security","paper filing"],"Cloud settings must be configured correctly.")
H("676.d.7.G",3,"A common challenge for cybersecurity professionals is that attackers:","constantly develop new techniques",["never use computers","always announce attacks","never change tactics"],"Threats evolve continually.")
H("676.d.7.G",4,"A shortage of trained workers is a challenge in cybersecurity known as the:","skills gap",["screen gap","memory leak","wireless dead zone"],"Demand exceeds trained talent.")
H("676.d.7.H",3,"An indicator of compromise (IOC) is:","evidence that a system may have been breached",["a software coupon","a backup schedule","a graphics card"],"IOCs signal a possible intrusion.")
H("676.d.7.H",4,"Which is a common warning sign that a computer may be compromised?","unexpected programs running and unusual network traffic",["a clean desktop","a new keyboard","a quiet fan only"],"Odd activity can indicate infection.")
H("676.d.7.I",3,"Many IoT devices are vulnerable because they often have:","default passwords and weak updates",["too much encryption","no internet","strong firewalls"],"IoT devices frequently ship insecure.")
H("676.d.7.I",4,"Changing the default credentials on a smart camera helps prevent:","unauthorized remote access",["screen glare","battery drain","slow video"],"Defaults are widely known to attackers.")
H("676.d.7.J",3,"A weakness in software that an attacker could exploit is called a:","vulnerability",["firewall","cookie","patch cable"],"A vulnerability is a flaw.")
H("676.d.7.J",4,"The method or code used to take advantage of a vulnerability is an:","exploit",["archive","antenna","update"],"Exploits abuse vulnerabilities.")
H("676.d.7.K",3,"Penetration testing is:","an authorized simulated attack to find weaknesses",["a way to make passwords public","random deletion of files","repairing monitors"],"Pen tests are permitted simulated attacks.")
H("676.d.7.K",4,"Which tool is commonly used by penetration testers to scan for open ports?","Nmap",["Photoshop","Excel","Notepad"],"Nmap maps hosts and ports.")
H("676.d.7.L",3,"The MITRE ATT&CK framework is a knowledge base of:","adversary tactics and techniques",["video game cheats","fonts","programming syntax"],"ATT&CK catalogs real attacker behavior.")
H("676.d.7.L",4,"The NIST Cybersecurity Framework organizes security activities into functions such as identify, protect, detect, respond and:","recover",["advertise","decorate","entertain"],"Recover completes the core functions.")
H("676.d.8.A",3,"Malware that secretly records what a user does and sends it to an attacker is:","spyware",["a backup tool","a firmware update","a driver"],"Spyware monitors users covertly.")
H("676.d.8.A",4,"Malware that encrypts a victim's files and demands payment is:","ransomware",["spyware","a rootkit","an updater"],"Ransomware holds data hostage.")
H("676.d.8.B",3,"Malware that disguises itself as legitimate software is called a:","Trojan horse",["worm","firewall","patch"],"Trojans trick users into installing them.")
H("676.d.8.B",4,"Malware that spreads by itself across networks without a user opening a file is a:","worm",["Trojan horse","cookie","macro"],"Worms self-replicate.")
H("676.d.8.C",3,"Ransomware-as-a-service lets criminals:","rent malware tools from developers",["delete their own malware","report attacks to police","eliminate viruses"],"Developers lease ready-made tools.")
H("676.d.8.C",4,"The as-a-service model has increased cybercrime because it:","lowers the skill needed to launch attacks",["requires more skill","makes attacks illegal to rent","bans all malware"],"Less technical criminals can attack.")
H("676.d.8.D",3,"Analysts reverse engineer malware to:","understand how it works and build detections",["advertise it","spread it faster","hide it"],"Analysis supports defenses.")
H("676.d.8.D",4,"Examining a suspicious program in an isolated environment so it cannot harm the network is called using a:","sandbox",["spreadsheet","mailbox","playlist"],"Sandboxes contain risky code.")
H("676.d.8.E",3,"Antivirus software commonly detects threats by comparing files to known:","signatures",["fonts","playlists","wallpapers"],"Signatures identify known malware.")
H("676.d.8.E",4,"Endpoint detection and response (EDR) tools monitor devices to:","detect and respond to suspicious activity",["print documents","raise screen brightness","compress photos"],"EDR watches and responds on endpoints.")
H("676.d.9.A",3,"System hardening means:","reducing a system's attack surface by securing its configuration",["making hardware heavier","adding more advertisements","turning off all security"],"Hardening shrinks exposure.")
H("676.d.9.A",4,"Which is an example of system hardening?","disabling unused services and ports",["opening all ports","using default passwords","skipping updates"],"Fewer open doors means fewer attacks.")
H("676.d.9.B",3,"The principle of least privilege says users should have:","only the access needed for their tasks",["full admin rights by default","no accounts at all","shared admin passwords"],"Minimal access limits damage.")
H("676.d.9.B",4,"Running daily tasks from an administrator account is risky because malware would then:","gain high-level privileges",["have no effects","lose all access","run slower only"],"Admin rights amplify damage.")
H("676.d.9.C",3,"A patch is a software update that mostly:","fixes security flaws and bugs",["changes the screen color","adds advertisements","deletes users"],"Patches repair known problems.")
H("676.d.9.C",4,"Unpatched operating systems are risky because attackers:","can use publicly known vulnerabilities",["cannot find them","lose interest","need physical access always"],"Known flaws are easy to exploit.")
H("676.d.9.D",3,"Turning on automatic software updates helps ensure:","security fixes are installed promptly",["fewer apps work","passwords reset daily","the device never restarts"],"Automation reduces delay.")
H("676.d.9.D",4,"Delaying updates for months can leave users exposed to:","known exploits",["new wallpapers","lower prices","better battery"],"Old software keeps old flaws.")
H("676.d.9.E",3,"Services that a computer does not need should be:","disabled",["multiplied","hidden in email","made public"],"Unneeded services add risk.")
H("676.d.9.E",4,"Changing default service settings, such as default accounts and ports, helps because defaults are:","well known to attackers",["always encrypted","legally required","impossible to change"],"Attackers try defaults first.")
H("676.d.9.F",3,"The 3-2-1 backup rule suggests keeping three copies of data on two types of media with:","one copy offsite",["no copies online","all copies in one room","zero copies"],"An offsite copy survives local disasters.")
H("676.d.9.F",4,"Regular backups help recover from ransomware because you can:","restore files without paying",["avoid updating","skip passwords","delete the OS"],"Backups remove the need to pay.")
H("676.d.9.G",3,"Enabling a host firewall helps secure a computer by:","filtering unwanted network traffic",["increasing screen size","adding storage","speeding up printing"],"Firewalls allow or block traffic.")
H("676.d.9.G",4,"Full-disk encryption protects data if a laptop is:","lost or stolen",["updated","renamed","plugged in"],"Encrypted disks are unreadable without a key.")
H("676.d.9.H",3,"Employees who lack security training are more likely to:","fall for phishing emails",["report all threats","use strong passwords","patch servers"],"Untrained users are easier targets.")
H("676.d.9.H",4,"Regular security awareness training mainly helps reduce:","human error",["electricity costs","paper use","screen glare"],"Training changes user behavior.")
H("676.d.10.A",3,"Which device connects different networks and forwards packets between them?","router",["switch","hub","monitor"],"Routers link networks together.")
H("676.d.10.A",4,"A switch mainly connects devices within the same:","local network",["planet","printer","power outlet"],"Switches operate inside a LAN.")
H("676.d.10.B",3,"An IP address identifies:","a device on a network",["a keyboard layout","a file type","a screen resolution"],"IP addresses locate devices.")
H("676.d.10.B",4,"Which is an example of an IPv4 address format?","192.168.1.10",["192.168.1.1.1.1","abc.def.ghi","12-34-56"],"IPv4 uses four numbers from 0 to 255.")
H("676.d.10.C",3,"A firewall rule that blocks all incoming traffic on port 23 (Telnet) prevents:","remote Telnet connections to that device",["all web browsing","local printing","screen sharing only"],"Blocking a port stops that service's traffic.")
H("676.d.10.C",4,"Firewalls often follow the idea of 'default deny', which means traffic is:","blocked unless a rule allows it",["allowed unless blocked","logged but ignored","encrypted by default"],"Default deny is the safer posture.")
H("676.d.10.D",3,"Port 22 is commonly used for:","Secure Shell (SSH)",["Telnet","web browsing (HTTP)","email delivery (SMTP)"],"SSH uses port 22.")
H("676.d.10.D",4,"HTTPS web traffic normally uses port:","443",["80","21","25"],"HTTPS defaults to 443.")
H("676.d.10.E",3,"Ports 20 and 21 are used by:","File Transfer Protocol (FTP)",["Secure Shell","DNS","HTTPS"],"FTP uses ports 20 and 21.")
H("676.d.10.E",4,"Telnet (port 23) is considered risky because it sends data:","unencrypted, including passwords",["only at night","encrypted twice","to no one"],"Telnet is plain text.")
H("676.d.10.F",3,"Which tool captures and analyzes network packets?","Wireshark",["Paint","Calculator","Notepad"],"Wireshark is a packet analyzer.")
H("676.d.10.F",4,"Nmap is commonly used to:","discover hosts and open ports",["edit photos","write essays","play music"],"Nmap scans networks.")
H("676.d.11.A",3,"Which password is strongest?","Tr!ckyL0ngPassphrase#47",["password123","qwerty","12345678"],"Length and variety add strength.")
H("676.d.11.A",4,"A strong password is generally:","long, unique and hard to guess",["short and memorable","a pet's name","the same everywhere"],"Strong passwords resist guessing.")
H("676.d.11.B",3,"Locking an account after several failed login attempts helps stop:","brute-force guessing",["power outages","slow printers","screen glare"],"Lockouts limit repeated guesses.")
H("676.d.11.B",4,"A common password policy requires a minimum:","length and a mix of character types",["number of friends","amount of storage","screen size"],"Length and complexity are standard rules.")
H("676.d.11.C",3,"A brute-force attack tries:","many possible combinations until one works",["one password only","only the correct password","passwords from a printer"],"Brute force tests many options.")
H("676.d.11.C",4,"A dictionary attack succeeds most often against passwords that are:","common words or simple variations",["long random strings","unique passphrases","multi-factor protected"],"Dictionary attacks try likely words.")
H("676.d.11.D",3,"Setting file permissions so only managers can edit a file is an example of:","access control",["file compression","defragmentation","screen calibration"],"Permissions restrict who can act.")
H("676.d.11.D",4,"A user who should only view a document should be given:","read-only permission",["full control","ownership","administrator rights"],"Least privilege limits actions.")
H("676.d.12.A",3,"On an operating system, an account with full control of settings and software is a(n):","administrator account",["guest account","standard account","service printer"],"Admins have the highest privileges.")
H("676.d.12.A",4,"Assigning users to a group such as 'Accounting' lets an administrator:","grant permissions to many users at once",["delete every user","hide the group","disable all security"],"Groups simplify permission management.")
H("676.d.12.B",3,"Authentication verifies who you are, while authorization determines:","what you are allowed to do",["when your device was built","how fast your network is","what color your screen is"],"Authorization sets permissions.")
H("676.d.12.B",4,"Role-based access control assigns permissions according to a user's:","job role",["favorite color","device brand","home address"],"RBAC ties access to roles.")
H("676.d.12.C",3,"Which pair is an example of multi-factor authentication?","a password plus a code sent to a phone",["two different passwords only","a username and a user ID","a password written twice"],"It combines different factor types.")
H("676.d.12.C",4,"A fingerprint scan is an example of something you:","are",["know","have","forget"],"Biometrics are inherence factors.")
H("676.d.12.D",3,"An air-gapped computer is one that is:","physically isolated from unsecured networks",["connected to the most networks","always on Wi-Fi","used only for gaming"],"Air gaps separate systems from outside networks.")
H("676.d.12.D",4,"A benefit of air-gapping a critical system is that it:","reduces exposure to remote attacks",["makes it faster","removes the need for passwords","guarantees no insider threats"],"No network path limits remote attacks.")
H("676.d.12.E",3,"Comparing a downloaded file's hash to the published hash helps verify its:","integrity",["color","author's age","download speed"],"Matching hashes mean the file is unchanged.")
H("676.d.12.E",4,"If a file changes by even one bit, its hash value will:","change completely",["stay the same","become shorter","vanish silently"],"Hashes are sensitive to any change.")
H("676.d.13.A",3,"Digital forensics is the process of:","collecting and analyzing digital evidence",["building faster chips","designing web fonts","painting screens"],"Forensics investigates digital evidence.")
H("676.d.13.A",4,"Organizations use digital forensics to:","investigate incidents and support legal action",["avoid keeping any records","speed up deliveries","choose office colors"],"Forensics reveals what happened.")
H("676.d.13.B",3,"A chain of custody document records:","who handled evidence and when",["the best desktop theme","the price of the device","the length of the cable"],"It tracks evidence handling.")
H("676.d.13.B",4,"A broken chain of custody can make digital evidence:","inadmissible or less trustworthy in court",["more valuable","automatically encrypted","faster to read"],"Unclear handling undermines evidence.")
H("676.d.13.C",3,"Which sequence lists the four steps of the forensic process in order?","collection, examination, analysis, reporting",["reporting, analysis, examination, collection","analysis, collection, reporting, examination","examination, reporting, collection, analysis"],"Collect, examine, analyze, then report.")
H("676.d.13.C",4,"In which forensic step do investigators draw conclusions from the examined data?","analysis",["collection","backup","deletion"],"Analysis interprets findings.")
H("676.d.13.D",3,"A digital forensics investigation is typically needed after:","a suspected data breach or policy violation",["a routine screen cleaning","a new wallpaper","a lunch break"],"Incidents trigger forensics.")
H("676.d.13.D",4,"Which situation most likely requires forensics?","evidence of employee data theft",["a keyboard that needs cleaning","a slow printer","a new desktop icon"],"Theft needs evidence collection.")
H("676.d.13.E",3,"Forensic tools can often recover:","deleted files and browsing history",["only paper documents","nothing at all","only new installs"],"Deleted data can often be recovered.")
H("676.d.13.E",4,"Metadata such as the time a file was created can help investigators:","build a timeline of events",["increase file size","change the owner","speed up the CPU"],"Timestamps order events.")
H("676.d.13.F",3,"An event log records:","system and security events with timestamps",["only photos","only emails sent","only battery levels"],"Logs track what happened and when.")
H("676.d.13.F",4,"Which log entry would most suggest suspicious activity?","hundreds of failed logins from one address in a minute",["one successful login","a scheduled update","a user logging out"],"Rapid failures suggest guessing attacks.")
H("676.d.14.A",3,"The main purpose of encrypting data is to:","keep it unreadable to unauthorized people",["make it larger","speed it up","delete it"],"Encryption protects confidentiality.")
H("676.d.14.A",4,"Encryption turns readable data, called plaintext, into unreadable data called:","ciphertext",["metadata","hypertext","source code"],"Ciphertext is encrypted output.")
H("676.d.14.B",3,"Julius Caesar is said to have protected messages with a:","shift cipher",["quantum key","hash table","firewall"],"The Caesar cipher shifts letters.")
H("676.d.14.B",4,"During World War II, Germany used the Enigma machine to:","encrypt military messages",["print newspapers","dial telephones","cool engines"],"Enigma was a cipher machine.")
H("676.d.14.C",3,"With a shift of 3, the letter A becomes:","D",["C","B","E"],"A to B to C to D.")
H("676.d.14.C",4,"Encrypting the word CAB with a shift of 1 (A becomes B) gives:","DBC",["BZA","CAB","ECD"],"C to D, A to B, B to C.")
H("676.d.14.D",3,"In public key encryption, which key is shared openly?","the public key",["the private key","the screen key","the home key"],"The public key can be distributed.")
H("676.d.14.D",4,"A message encrypted with someone's public key can be decrypted with their:","private key",["public key","username","IP address"],"Only the private key unlocks it.")
H("676.d.14.E",3,"Symmetric encryption uses:","the same key to encrypt and decrypt",["two different keys","no keys","a public directory"],"One shared secret key.")
H("676.d.14.E",4,"Compared with symmetric encryption, asymmetric encryption is typically:","slower but easier for key exchange",["faster and key-free","unable to encrypt","the same speed always"],"Asymmetric solves key distribution at a speed cost.")
H("676.d.15.A",3,"A vulnerability that is exploited before a patch exists is called a:","zero-day",["one-day sale","dead pixel","blank page"],"Zero-days have no fix yet.")
H("676.d.15.A",4,"Why do unpatched vulnerabilities leave systems open to attack?","attackers can use the flaw to gain access",["they make hardware louder","they delete only unused files","they prevent logins for everyone"],"Known flaws provide an entry point.")
H("676.d.15.B",3,"Attackers often target people because users are:","easier to trick than strong technical defenses",["never online","unable to click","always expert"],"Humans can be manipulated.")
H("676.d.15.B",4,"The weakest link in many security systems is the:","human user",["power cable","monitor stand","keyboard cover"],"Human error is the most common cause.")
H("676.d.15.C",3,"The part of malware that carries out the harmful action is the:","payload",["firewall","logo","update"],"The payload is the damaging action.")
H("676.d.15.C",4,"Capturing and reading data as it travels across a network is called:","packet sniffing",["port forwarding","disk cleanup","file sharing"],"Sniffers capture network packets.")
H("676.d.15.D",3,"Code that stays hidden until a trigger, such as a date, then performs harmful actions is a:","logic bomb",["cookie","backup","wallpaper"],"Logic bombs activate on conditions.")
H("676.d.15.D",4,"An employee misusing their authorized access to steal data is an:","insider threat",["outside visitor","power failure","software update"],"Insiders already hold access.")
H("676.d.15.E",3,"An attacker secretly intercepting communication between two parties is a:","man-in-the-middle attack",["backup","reboot","calibration"],"The attacker sits between sender and receiver.")
H("676.d.15.E",4,"A DDoS attack tries to:","overwhelm a service so legitimate users cannot reach it",["fix a website","encrypt backups","patch a server"],"Flooding denies service.")
H("676.d.15.F",3,"A deceptive email that tricks you into entering your password on a fake site is:","phishing",["backing up","streaming","pinging"],"Phishing impersonates trusted sources.")
H("676.d.15.F",4,"Phishing through text messages is called:","smishing",["vishing","pharming","tailgating"],"Smishing uses SMS.")
H("676.d.15.G",3,"Entering SQL commands into a web form to manipulate a database is:","SQL injection",["port scanning","screen scraping","packet loss"],"Unsanitized input lets attackers run queries.")
H("676.d.15.G",4,"Cross-site scripting (XSS) lets an attacker:","run malicious scripts in other users' browsers",["repair a router","print remote documents","speed up a database"],"XSS injects scripts into pages.")
H("676.d.16.A",3,"Connecting to an open public Wi-Fi network is riskier because traffic may be:","intercepted by others on the network",["always encrypted by default","limited to you only","blocked from all sites"],"Open networks expose traffic.")
H("676.d.16.A",4,"A VPN on public Wi-Fi helps by:","encrypting traffic between your device and the VPN server",["increasing your data speed always","hiding the router","removing the password"],"VPNs protect data in transit.")
H("676.d.16.B",3,"A supply chain attack compromises a target by:","tampering with trusted software or hardware from a supplier",["cleaning the supplier's office","slowing all shipping","changing the screen"],"Attackers abuse trusted vendors.")
H("676.d.16.B",4,"A solution to reduce device vulnerabilities on a network is:","network segmentation and regular patching",["sharing admin passwords","disabling all logs","using default settings"],"Segmentation and patching limit exposure.")
H("676.d.16.C",3,"HTTPS differs from HTTP mainly because HTTPS:","encrypts the data sent between browser and server",["is slower always","uses no ports","blocks all pictures"],"HTTPS adds TLS encryption.")
H("676.d.16.C",4,"The padlock icon in a browser address bar indicates the connection uses:","TLS encryption",["a faster printer","a bigger screen","a free coupon"],"Padlocks show an encrypted connection.")
H("676.d.16.D",3,"An SSID is the:","name of a wireless network",["password of a router","serial number of a phone","speed of a cable"],"The SSID identifies the network.")
H("676.d.16.D",4,"Hiding an SSID is generally considered:","weak security because the name can still be discovered",["unbreakable protection","the same as encryption","required by law"],"Hidden names are easy to detect.")
H("676.d.16.E",3,"MAC spoofing is when an attacker:","falsifies a device's hardware address to impersonate it",["upgrades the router","prints a label","encrypts a drive"],"Spoofing fakes identity.")
H("676.d.16.E",4,"An 'evil twin' attack uses a fake wireless access point that:","imitates a legitimate network to capture user data",["blocks all devices","fixes weak signals","increases speed"],"Victims connect to the rogue network.")
H("676.d.17.A",3,"Application security focuses on:","protecting software from threats throughout its life",["designing keyboards","choosing office chairs","painting logos"],"AppSec covers the software lifecycle.")
H("676.d.17.A",4,"Security is best built into software:","from the start of design",["only after release","never","only after a breach"],"Early security is cheaper and stronger.")
H("676.d.17.B",3,"Reviewing code for security flaws before release is called:","a secure code review",["a screen test","a font review","a speed run"],"Reviews catch flaws early.")
H("676.d.17.B",4,"Using input validation and parameterized queries are examples of:","secure coding practices",["hardware upgrades","marketing tactics","data loss"],"They prevent injection attacks.")
H("676.d.17.C",3,"A vulnerability scanner is a tool that:","checks systems for known weaknesses",["writes code for you","blocks all emails","cleans keyboards"],"Scanners search for known flaws.")
H("676.d.17.C",4,"After a vulnerability scan, results are typically used to:","prioritize and fix the discovered issues",["delete the scanner","ignore high-risk items","publish them online"],"Findings drive remediation.")
H("676.d.17.D",3,"A buffer overflow occurs when a program:","writes more data into memory than the space allows",["reads too little data","opens too many windows","prints a blank page"],"Excess data spills into adjacent memory.")
H("676.d.17.D",4,"Buffer overflows can let attackers:","run their own code or crash the program",["repair the program","speed up the network","restore old files"],"Overflows can hijack execution.")
H("676.d.17.E",3,"Releasing an app with known security flaws can expose users to:","data theft and loss of trust",["better reviews","more storage","free upgrades"],"Insecure apps harm users.")
H("676.d.17.E",4,"A company that ships insecure software may face:","lawsuits, fines and reputation damage",["automatic awards","lower scrutiny","guaranteed profits"],"Insecure releases carry consequences.")
H("676.d.18.A",3,"In risk assessment, an asset is:","anything of value that needs protection",["a type of virus","a network cable only","a bug report"],"Assets are what you protect.")
H("676.d.18.A",4,"A written list of an organization's hardware and software is an:","inventory",["invoice","index","incident"],"Inventories track assets.")
H("676.d.18.B",3,"Buying cyber insurance to shift financial loss to another party is risk:","transference",["acceptance","avoidance","denial"],"Transference passes risk to others.")
H("676.d.18.B",4,"Deciding not to offer a risky service at all is risk:","avoidance",["acceptance","transference","mitigation"],"Avoidance eliminates the activity.")
H("676.d.18.C",3,"A risk matrix ranks risks by comparing their likelihood and their:","potential impact",["screen size","brand","color"],"Matrices combine likelihood and impact.")
H("676.d.18.C",4,"Which scoring system is commonly used to rate the severity of software vulnerabilities?","CVSS (Common Vulnerability Scoring System)",["GPA","BMI","SAT"],"CVSS scores vulnerability severity.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_82.jsonl"))
